window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-5dc38d6976d6221f"]={"versions": [{"id": "FIG-5dc38d6976d6221f", "releases": ["R23-11", "R24-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Anwendungsfalldiagramm (Use Case Diagram) der AUTOSAR Adaptive Platform zur Darstellung des Anwendungsfalls <strong>Manage Watchdog</strong> im funktionalen Cluster <strong>Platform Health Management</strong> sowie dessen Interaktionsbeziehungen zu Akteuren und weiteren funktionalen Clustern.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteur:</strong></li>\n<li><code>Watchdog</code> (Paket <code>Actors</code>): Externer Akteur (Hardware- oder System-Watchdog).</li>\n<li><strong>Systemgrenzen & Cluster:</strong></li>\n<li><code>Adaptive Platform</code>: Übergeordnetes System.</li>\n<li><code>Platform Health Management</code>: Funktionales Cluster der Adaptive Platform, das den Anwendungsfall kapselt.</li>\n<li><strong>Anwendungsfall:</strong></li>\n<li><code>Manage Watchdog</code> (<code>«aapUseCase»</code>).</li>\n<li><strong>Beteiligte Komponenten:</strong></li>\n<li><code>State Management</code> (<code>«aapFunctionalCluster»</code>, Ausprägung <code>daemon-based</code>): Funktionales Cluster der Adaptive Platform.</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Assoziation <code>«aapParticipates»</code> zwischen dem Akteur <code>Watchdog</code> und dem Use Case <code>Manage Watchdog</code>.</li>\n<li>Assoziation <code>«aapParticipates»</code> zwischen dem Use Case <code>Manage Watchdog</code> und der Komponente <code>State Management</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Anwendungsfall <code>Manage Watchdog</code> bindet das funktionale Cluster <code>Platform Health Management</code> an den externen Akteur <code>Watchdog</code> sowie das funktionale Cluster <code>State Management</code> an. Über diese Interaktion steuert oder triggert die Adaptive Platform den Watchdog und synchronisiert Überwachungs- bzw. Wiederanlaufzustände mit dem Zustandsmanagement.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Spezifikation der Beteiligung am Watchdog-Management im Rahmen des Platform Health Managements (PHM). Entwickler von PHM und State Management müssen Schnittstellen und Abläufe vorsehen, um Watchdog-Triggerung und Zustandsreaktionen aufeinander abzustimmen.</p>"}, {"id": "FIG-5499c12a6b6d2290", "releases": ["R25-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Anwendungsfalldiagramm (Use Case Diagram) der AUTOSAR Adaptive Platform zur Darstellung des Anwendungsfalls <strong>Manage Watchdog</strong> innerhalb des funktionalen Clusters <strong>Platform Health Management</strong> und dessen Interaktion mit einem externen Akteur.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><strong>Akteur:</strong></li>\n<li><code>Watchdog</code> (Paket <code>Actors</code>): Externer Akteur (Hardware- oder System-Watchdog).</li>\n<li><strong>Systemgrenzen & Cluster:</strong></li>\n<li><code>Adaptive Platform</code>: Übergeordnetes System.</li>\n<li><code>Platform Health Management</code>: Funktionales Cluster der Adaptive Platform, das den Anwendungsfall kapselt.</li>\n<li><strong>Anwendungsfall:</strong></li>\n<li><code>Manage Watchdog</code> (<code>«aapUseCase»</code>).</li>\n<li><strong>Beziehungen:</strong></li>\n<li>Assoziation <code>«aapParticipates»</code> zwischen dem Akteur <code>Watchdog</code> und dem Use Case <code>Manage Watchdog</code>.</li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Der Anwendungsfall <code>Manage Watchdog</code> beschreibt die isolierte Interaktion zwischen dem funktionalen Cluster <code>Platform Health Management</code> und dem externen Akteur <code>Watchdog</code>, insbesondere zur Überwachung, Bedienung und Triggerung des Watchdogs.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Architektonische Spezifikation für das Platform Health Management (PHM). Das Watchdog-Management ist als direkte Beziehung zwischen PHM und dem Watchdog-Akteur definiert, ohne modellierte direkte Beteiligung weiterer funktionaler Cluster an diesem Anwendungsfall.</p>"}], "trans": [{"from": "FIG-5dc38d6976d6221f", "to": "FIG-5499c12a6b6d2290", "fr": "R24-11", "tr": "R25-11", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\">\n<li>Komponente <code>State Management</code> (<code>«aapFunctionalCluster»</code>, <code>daemon-based</code>) entfernt.</li>\n<li>Assoziation <code>«aapParticipates»</code> zwischen dem Use Case <code>Manage Watchdog</code> und <code>State Management</code> entfernt.</li>\n</ul>"}]};
